Trie.ejemplo:
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

def insert(root, word):
    node = root
    for ch in word:
        node = node.children.setdefault(ch, TrieNode())
    node.is_end = True

Árboles binarios.ejemplo:
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def inorden(root):
    if not root:
        return []
    return inorden(root.left) + [root.val] + inorden(root.right)
